// Digi's Combat and Loot: Instant Loot, Boss Stars After Defeat, Keep Loaded, Grapple Aim, Arrow Effects, Floating Loot, Breeding Status, Legends Toggle, Charm Scaling, Hit Effects, Passive Forsaken Powers.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiCombat
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("com.jotunn.jotunn")]
    [BepInDependency("MidnightsFX.StarLevelSystem", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("randyknapp.mods.epicloot", BepInDependency.DependencyFlags.SoftDependency)]
    [Jotunn.Utils.NetworkCompatibility(Jotunn.Utils.CompatibilityLevel.VersionCheckOnly, Jotunn.Utils.VersionStrictness.Minor)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.combat";
        public const string Name = "Digi's Combat and Loot";
        public const string Version = "1.0.27";

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::InstantLoot.Plugin), "Instant Loot", "digi.valheim.instantloot", "Monsters drop their loot the moment they die, shown in a stacked pickup list.", null, true),
            new ModuleInfo(typeof(global::BossStarsAfterDefeat.Plugin), "Boss Stars After Defeat", "digi.valheim.bossstarsafterdefeat", "Every boss you beat allows more stars on creatures, with more trophies from starred ones.", new[] { "MidnightsFX.StarLevelSystem" }, true),
            new ModuleInfo(typeof(global::QuiverToggle.Plugin), "Quiver Toggle", "digi.valheim.quivertoggle", "Better Archery: hide the quiver on your back (and/or on other players).", new[] { "ishid4.mods.betterarchery" }, true),
            new ModuleInfo(typeof(global::KeepLoaded.Plugin), "Keep Loaded", "digi.valheim.keeploaded", "Crossbows and the grappling hook stay loaded when you switch weapons.", null, true),
            new ModuleInfo(typeof(global::GrappleAim.Plugin), "Grapple Aim", "digi.valheim.grappleaim", "The crosshair turns red when the grappling hook would not catch where you aim.", null, true),
            new ModuleInfo(typeof(global::ArrowEffects.Plugin), "Arrow Effects", "digi.valheim.arroweffects", "Tone down the effects of fire, poison and frost arrows.", null, true),
            new ModuleInfo(typeof(global::FloatingLoot.Plugin), "Floating Loot", "digi.valheim.floatingloot", "Dropped items float on water instead of sinking.", null, true),
            new ModuleInfo(typeof(global::BreedingStatus.Plugin), "Breeding Status", "digi.valheim.breedingstatus", "Hover a tame animal to see why it is or isn't breeding.", null, true),
            new ModuleInfo(typeof(global::LegendsToggle.Plugin), "Legends Toggle", "digi.valheim.legendstoggle", "The host turns Valheim Legends on or off for everyone, live.", new[] { "com.jotunn.jotunn" }, true),
            new ModuleInfo(typeof(global::CharmScaling.Plugin), "Charm Scaling", "digi.valheim.charmscaling", "The Enchanter's Charm lasts longer as your Alteration skill grows.", new[] { "ValheimLegends" }, true),
            // Replaces Digitalroot's Passive Forsaken Powers: its ID as the "separate mod", so both never run at once.
            // Replaces Wheeze's Dimmer Combat Particle Effects (its ID as the "separate mod").
            new ModuleInfo(typeof(global::HitEffects.Plugin), "Hit Effects", "wheeze.valheim.dimmercombatparticleeffects", "Fades the effects that cover creatures in combat (burning, frost, poison, hit bursts), so you see their attacks coming.", null, true),
            new ModuleInfo(typeof(global::PassivePowers.Plugin), "Passive Forsaken Powers", "digitalroot.mods.passiveforsakenpowers.jvl", "Forsaken powers are always on: the one you chose at a boss stone, or every power you unlocked.", null, true),
            new ModuleInfo(typeof(global::PowerPicker.Plugin), "Power Picker", "digi.valheim.powerpicker", "P opens a window with every forsaken power (icon, name, what it does): choose any whose boss trophy hangs on its stone, without going to the start.", null, true),
            new ModuleInfo(typeof(global::CapeFeatherFall.Plugin), "Cape Feather Fall", "digi.valheim.capefeatherfall", "A switch per vanilla cape that gives it feather fall, like the Feather Cape.", null, true),
            new ModuleInfo(typeof(global::StaffAim.Plugin), "Staff Aim", "digi.valheim.staffaim", "Lightning Strike lands where your crosshair is: no random spread, and the arc is worked out to reach that spot.", null, true),
            new ModuleInfo(typeof(global::SafeTames.Plugin), "Safe Tames", "digi.valheim.safetames", "Tamed animals take no damage from players or other tames (staff blasts, bombs, fire, PvP hits); the Butcher Knife still works.", null, true),
            new ModuleInfo(typeof(global::TameTeleport.Plugin), "Tame Teleport", "digi.valheim.tameteleport", "Tamed animals that follow you come along when you teleport: through a portal, with Portal List or any other teleport.", null, true),
        };
    }
}
